from pathlib import Path
import re,json,html,markdown

root=Path(__file__).parent
base='https://raw.githubusercontent.com/EyeVisionsNL/SDRCC/e807e4aa5ca56bb72dc76efbea117077be94ce0a/'
pages=[["Home","Start here","overview","Your station. Your signals.","Ships, aircraft, radio and satellites in one station."],["Installation","Installation","overview","Install SDRCC.","Ubuntu setup in a few clear steps."],["First-steps","First steps","overview","Meet your receivers.","Connect and test your SDR hardware."],["Marine-and-ATIS","Marine & ATIS","marine","Which ship was that?","Listen to Marine voice and match a possible vessel."],["Radio-and-aircraft","Radio & aircraft","aviation","Explore the airwaves.","Tune radio and follow aircraft."],["Satellite-missions","Satellite missions","satellite","Catch a satellite pass.","Plan, receive and view results."],["Android-companion","Android app","marine","Your station on your phone.","Maps, audio and selected controls."],["Updates-and-troubleshooting","Updates & help","logs","Keep everything running.","Safe updates and practical first checks."]]
def url(slug): return 'index.html' if slug=='Home' else slug.lower()+'.html'
nav=''.join(f'<a href="{url(p[0])}" DATA-{p[0]}><span>{i:02}</span> &nbsp; {html.escape(p[1])}</a>' for i,p in enumerate(pages))
search=[]
for idx,(slug,label,scene,title,subtitle) in enumerate(pages):
    source=(root/'source'/f'{slug}.md').read_text()
    source=re.sub(r'\[\[([^\]]+)\]\]',lambda m:f'[{"Android app" if m[1]=="Android companion" else m[1]}]({url(m[1].replace(" ","-"))})',source)
    source=source.replace('https://raw.githubusercontent.com/EyeVisionsNL/SDRCC/main/',base)
    source=re.sub(r'^# .+\n','',source,count=1,flags=re.M)
    md=markdown.Markdown(extensions=['tables','fenced_code','toc'])
    body=md.convert(source)
    search.append({'title':label,'url':url(slug),'text':re.sub('<[^>]+>',' ',body)})
    if idx==0:
        # Compact welcome cards and companion project link.
        body="<div class=\"welcome\"><strong>Welcome aboard.</strong> Radio, ships, aircraft and satellites — all in one SDRCC station.</div><div class=\"section-head\"><h2>Choose your guide</h2><span>07 SHORT GUIDES · ONE STATION</span></div><div class=\"cards\"><a class=\"card\" href=\"installation.html\"><img src=\"https://raw.githubusercontent.com/EyeVisionsNL/SDRCC/e807e4aa5ca56bb72dc76efbea117077be94ce0a/dashboard/static/assets/banners/overview-panorama.webp\" alt=\"\" loading=\"lazy\"><div class=\"card-body\"><span class=\"num\">GUIDE 01</span><h3>Installation</h3><p>Ubuntu setup in a few clear steps.</p><span class=\"arrow\">Open guide ↗</span></div></a><a class=\"card\" href=\"first-steps.html\"><img src=\"https://raw.githubusercontent.com/EyeVisionsNL/SDRCC/e807e4aa5ca56bb72dc76efbea117077be94ce0a/dashboard/static/assets/banners/overview-panorama.webp\" alt=\"\" loading=\"lazy\"><div class=\"card-body\"><span class=\"num\">GUIDE 02</span><h3>First steps</h3><p>Connect and test your SDR hardware.</p><span class=\"arrow\">Open guide ↗</span></div></a><a class=\"card\" href=\"marine-and-atis.html\"><img src=\"https://raw.githubusercontent.com/EyeVisionsNL/SDRCC/e807e4aa5ca56bb72dc76efbea117077be94ce0a/dashboard/static/assets/banners/marine-panorama.webp\" alt=\"\" loading=\"lazy\"><div class=\"card-body\"><span class=\"num\">GUIDE 03</span><h3>Marine & ATIS</h3><p>Listen to Marine voice and match a possible vessel.</p><span class=\"arrow\">Open guide ↗</span></div></a><a class=\"card\" href=\"radio-and-aircraft.html\"><img src=\"https://raw.githubusercontent.com/EyeVisionsNL/SDRCC/e807e4aa5ca56bb72dc76efbea117077be94ce0a/dashboard/static/assets/banners/aviation-panorama.webp\" alt=\"\" loading=\"lazy\"><div class=\"card-body\"><span class=\"num\">GUIDE 04</span><h3>Radio & aircraft</h3><p>Tune radio and follow aircraft.</p><span class=\"arrow\">Open guide ↗</span></div></a><a class=\"card\" href=\"satellite-missions.html\"><img src=\"https://raw.githubusercontent.com/EyeVisionsNL/SDRCC/e807e4aa5ca56bb72dc76efbea117077be94ce0a/dashboard/static/assets/banners/satellite-panorama.webp\" alt=\"\" loading=\"lazy\"><div class=\"card-body\"><span class=\"num\">GUIDE 05</span><h3>Satellite missions</h3><p>Plan, receive and view results.</p><span class=\"arrow\">Open guide ↗</span></div></a><a class=\"card\" href=\"android-companion.html\"><img src=\"https://raw.githubusercontent.com/EyeVisionsNL/SDRCC/e807e4aa5ca56bb72dc76efbea117077be94ce0a/dashboard/static/assets/banners/marine-panorama.webp\" alt=\"\" loading=\"lazy\"><div class=\"card-body\"><span class=\"num\">GUIDE 06</span><h3>Android app</h3><p>Maps, audio and selected controls.</p><span class=\"arrow\">Open guide ↗</span></div></a><a class=\"card\" href=\"updates-and-troubleshooting.html\"><img src=\"https://raw.githubusercontent.com/EyeVisionsNL/SDRCC/e807e4aa5ca56bb72dc76efbea117077be94ce0a/dashboard/static/assets/banners/logs-panorama.webp\" alt=\"\" loading=\"lazy\"><div class=\"card-body\"><span class=\"num\">GUIDE 07</span><h3>Updates & help</h3><p>Safe updates and practical first checks.</p><span class=\"arrow\">Open guide ↗</span></div></a></div><section class=\"bridge-callout\"><div class=\"eyebrow\">A LIGHTER OPTION</div><h2>Already receiving AIS?</h2><p>Have AIS-catcher and a second RTL-SDR? <strong>AIS-ATIS Bridge</strong> adds marine VHF, ATIS decoding and vessel matching — without aircraft or satellite features.</p><a class=\"button primary\" href=\"https://eyevisionsnl.github.io/AIS-ATIS-Bridge/\">Explore AIS-ATIS Bridge ↗</a></section><p class=\"quick-path\"><strong>New here?</strong> Follow <a href=\"installation.html\">Installation</a> → <a href=\"first-steps.html\">First steps</a>, then choose what to receive. <a href=\"https://github.com/EyeVisionsNL/SDRCC/discussions\">Questions & ideas ↗</a></p>"
        main=body
    else:
        main=f'<div class="article-wrap"><article class="article">{body}</article><aside class="toc" aria-label="On this page"><strong>ON THIS PAGE</strong>{md.toc}</aside></div>'
    prev=pages[idx-1] if idx else None
    nxt=pages[idx+1] if idx+1<len(pages) else None
    pager='<div class="pager">'+(f'<a href="{url(prev[0])}">← {html.escape(prev[1])}</a>' if prev else '<span></span>')+(f'<a href="{url(nxt[0])}">{html.escape(nxt[1])} →</a>' if nxt else '<a href="index.html">Back to start ↑</a>')+'</div>'
    active=re.sub(r' DATA-([^ >]+)',lambda m:' aria-current="page"' if m[1]==slug else '',nav)
    buttons='<div class="buttons"><a class="button primary" href="installation.html">Get started →</a><a class="button" href="android-companion.html">Android app ↗</a></div>' if idx==0 else ''
    doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{html.escape(subtitle)} SDRCC documentation and practical guides."><meta name="theme-color" content="#0f172a"><title>{html.escape(label)} · SDRCC Guide</title><link rel="icon" href="{base}dashboard/static/assets/sdrcc.png"><link rel="stylesheet" href="style.css?v=20261021d"><script src="app.js?v=20261017c" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header class="top"><a class="brand" href="index.html"><img src="{base}dashboard/static/assets/sdrcc.png" alt=""> <span>SDRCC<small>THE FIELD GUIDE</small></span></a><div class="top-links"><a href="https://github.com/EyeVisionsNL/SDRCC">GitHub ↗</a><a href="android-companion.html">Android app</a><span class="pill">● &nbsp; LISTEN · DECODE · EXPLORE</span><button class="menu" aria-label="Toggle navigation" aria-expanded="false" aria-controls="sidebar">☰</button></div></header><div class="layout"><aside class="sidebar" id="sidebar"><div class="eyebrow">STATION HANDBOOK</div><div class="search"><label for="search" class="eyebrow">Find a guide</label><input id="search" type="search" placeholder="Search AIS, Android, updates…" autocomplete="off"><div class="search-results" aria-live="polite"></div></div><nav aria-label="Guides">{active}</nav><div class="side-note">Radio · AIS · ATIS · ADS-B<br>Satellites · Android<br><br>Made for curious listeners.<br><a href="https://github.com/EyeVisionsNL/SDRCC/discussions">Questions & ideas ↗</a><br><a href="https://github.com/EyeVisionsNL/SDRCC/wiki">Original GitHub Wiki ↗</a></div></aside><main class="content" id="main"><div class="crumb">SDRCC / Documentation / {html.escape(label)}</div><section class="hero"><div class="hero-media"><img class="hero-image" src="{base}dashboard/static/assets/banners/{scene}-panorama.webp" alt="SDRCC {scene} panorama"><div class="radar" aria-hidden="true"><div class="sweep"></div><i></i><i></i><i></i></div></div><div class="hero-copy"><div class="eyebrow">{'WELCOME TO SDR CONTROL CENTER' if idx==0 else 'THE SDRCC GUIDE / '+label.upper()}</div><h1>{html.escape(title)}</h1><p>{html.escape(subtitle)}</p>{buttons}</div></section>{main}{pager}<footer class="footer"><span>SDRCC — SDR Control Center · Listen. Decode. Analyze. Share.</span><span>SDRCC user guide</span></footer></main></div><dialog aria-label="Enlarged screenshot"><button aria-label="Close screenshot">×</button><img alt=""></dialog></body></html>'''
    (root/url(slug)).write_text(doc)
(root/'search.json').write_text(json.dumps(search,ensure_ascii=False))
(root/'.nojekyll').write_text('')
print(f'Built {len(pages)} pages with local navigation and full-text guide search.')
